import { supabase, isSupabaseConfigured } from './supabaseClient';

// --- Types ---
type CollectionName = 'portfolio' | 'specials' | 'showroom' | 'bookings' | 'expenses' | 'inventory' | 'settings' | 'invoices' | 'clients';
type Listener = (data: any[]) => void;
